  "repair_strategy": "Modify the Escape case in the navigate function to only close the list, removing the input value clearing and the 'clear' event emission.",
  "edits": [
    {
      "path": "src/controllers/listController.js",
      "sha256": "913fcec2ffc448fd458cae19dd873623256f7e1c1ba3eab15225d68f74351f8f",
      "before": "/**
 * List navigation handler
 *
 * @param {Object} event - keydown press event Object
 * @param {Object} ctx - autoComplete.js context
 */
const navigate = (event, ctx) => {
  // Check pressed key
  switch (event.keyCode) {
    // Down/Up arrow
    case 40:
    case 38:
      event.preventDefault();
      // Move cursor based on pressed key
      event.keyCode === 40 ? next(ctx) : previous(ctx);

      break;
    // Enter
    case 13:
      if (!ctx.submit) event.preventDefault();
      // If cursor moved
      if (ctx.cursor >= 0) select(ctx, event);

      break;
    // Tab
    case 9:
      // Select on Tab if enabled
      if (ctx.resultsList.tabSelect && ctx.cursor >= 0) select(ctx, event);

      break;
    // Esc
    case 27:
      // Clear "input" value
      ctx.input.value = "";
      eventEmitter('clear', ctx);

      close(ctx);
      break;
  }
};",
      "after": "/**
 * List navigation handler
 *
 * @param {Object} event - keydown press event Object
 * @param {Object} ctx - autoComplete.js context
 */
const navigate = (event, ctx) => {
  // Check pressed key
  switch (event.keyCode) {
    // Down/Up arrow
    case 40:
    case 38:
      event.preventDefault();
      // Move cursor based on pressed key
      event.keyCode === 40 ? next(ctx) : previous(ctx);

      break;
    // Enter
    case 13:
      if (!ctx.submit) event.preventDefault();
      // If cursor moved
      if (ctx.cursor >= 0) select(ctx, event);

      break;
    // Tab
    case 9:
      // Select on Tab if enabled
      if (ctx.resultsList.tabSelect && ctx.cursor >= 0) select(ctx, event);

      break;
    // Esc
    case 27:
      // Close the list without clearing the input value
      close(ctx);
      break;
  }
};"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can dismiss the suggestion list with Escape while preserving their typed input, consistent with WCAG 2.1.1 (Keyboard) and ARIA APG combobox pattern.",
  "functional_risks": [
    "Existing integrations listening for the 'clear' event on Escape may no longer receive it. However, the 'clear' event is not documented in the public API and its removal aligns with standard combobox behavior."
  ],
  "verification_requirements": [
    "The existing journey test (Escape press) should now pass, asserting that the list closes, focus remains on the input, and form data reflects the typed value.",
    "Ensure ArrowDown and Enter selection still works (regression guard)."
  ]
}

